137|  const stateRef    = useRef({
138|    blinkState: 0, blinkTimer: Math.random() * 180 + 120,
139|    tiltAngle: 0,  tiltTarget: 0,
140|    noiseOff: Math.random() * 1000,
141|    bob: 0,
142|  });
143|
144|  useEffect(() => {
145|    loadedRef.current = false;
146|    landmarkRef.current = null;
147|    const img = new Image();
148|    img.crossOrigin = "anonymous";
149|    img.onload = () => {
150|      imgRef.current = img;
151|      loadedRef.current = true;
152|      // Attempt face-api.js landmark detection on the loaded image
153|      ensureFaceApi(async (ok) => {
154|        if (!ok || !imgRef.current) return;
155|        try {
156|          const fa  = window.faceapi;
157|          const res = await fa
158|            .detectSingleFace(imgRef.current, new fa.TinyFaceDetectorOptions({ scoreThreshold: 0.3 }))
159|            .withFaceLandmarks(true);
160|          if (!res) return;
161|          const lm   = res.landmarks;
162|          const box  = res.detection.box; // { x, y, width, height } in natural px
163|          const natW = imgRef.current.naturalWidth;
164|          const natH = imgRef.current.naturalHeight;
165|          // Expand the face box by a padding factor so we see forehead + chin
166|          const pad  = box.width * 0.45;
167|          const faceX = Math.max(0, box.x - pad);
168|          const faceY = Math.max(0, box.y - pad * 1.1); // extra top for forehead
169|          const faceW = Math.min(natW - faceX, box.width  + pad * 2);
170|          const faceH = Math.min(natH - faceY, box.height + pad * 2.2);
171|          landmarkRef.current = {
172|            leftEye:  lm.getLeftEye(),
173|            rightEye: lm.getRightEye(),
174|            mouth:    lm.getMouth(),
175|            natW, natH,
176|            // Face crop region (used to zoom canvas onto the face)
177|            faceBox: { x: faceX, y: faceY, w: faceW, h: faceH },
178|          };
179|        } catch (_) { /* silent fallback — animation continues without landmarks */ }
180|      });
181|    };
182|    img.onerror = () => { loadedRef.current = false; };
183|    img.src = avatar.img;
184|  }, [avatar.img]);
