186|  useEffect(() => {
187|    const canvas = canvasRef.current;
188|    if (!canvas) return;
189|    const ctx = canvas.getContext("2d");
190|    const dpr = window.devicePixelRatio || 1;
191|    canvas.width  = size * dpr;
192|    canvas.height = size * dpr;
193|    canvas.style.width  = size + "px";
194|    canvas.style.height = size + "px";
195|    ctx.scale(dpr, dpr);
196|    const s = stateRef.current;
197|
198|    const animate = () => {
199|      frameRef.current++;
200|      const f = frameRef.current;
201|      const t = (f + s.noiseOff) * 0.01;
202|      ctx.clearRect(0, 0, size, size);
203|
204|      // ── Update motion state ──
205|      s.blinkTimer--;
206|      if (s.blinkTimer <= 0 && s.blinkState === 0) s.blinkState = 1;
207|      if      (s.blinkState === 1) s.blinkState = 2;
208|      else if (s.blinkState === 2) s.blinkState = 3;
209|      else if (s.blinkState === 3) { s.blinkState = 0; s.blinkTimer = Math.random() * 200 + 100; }
