211|      if (isSpeaking || isListening) {
212|        s.tiltTarget = noise(t * 0.8) * 0.04 + Math.sin(f * 0.031) * 0.02;
213|      } else {
214|        s.tiltTarget = noise(t * 0.3) * 0.012;
215|      }
216|      s.tiltAngle += (s.tiltTarget - s.tiltAngle) * 0.04;
217|
218|      // ── Clip to circle ──
219|      ctx.save();
220|      ctx.beginPath();
221|      ctx.arc(size / 2, size / 2, size / 2 - 2, 0, Math.PI * 2);
