290|          const bh  = (eyeW * 0.12) * bp;
291|          const ex  = size / 2 - eyeW / 2;
292|          const bg  = ctx.createLinearGradient(0, eyeY - bh, 0, eyeY + bh);
293|          bg.addColorStop(0,   "rgba(0,0,0,0)");
294|          bg.addColorStop(0.5, `rgba(8,9,20,${bp * 0.90})`);
295|          bg.addColorStop(1,   "rgba(0,0,0,0)");
296|          ctx.fillStyle = bg;
297|          ctx.fillRect(ex, eyeY - bh, eyeW, bh * 2);
