317|        ctx.textBaseline = "middle";
318|        ctx.fillText(avatar.label[0], size / 2, size / 2);
319|      }
320|      ctx.restore();
321|
322|      // Speaking voice wave — pinned to bottom edge, not over the face
323|      if (isSpeaking || isListening) {
324|        const waveAmp = isSpeaking
325|          ? 5 + noise(t * 4) * 4 + Math.sin(f * 0.17) * 2
326|          : 2 + Math.sin(f * 0.14) * 1.5;
327|        const waveY = size * 0.91;
328|        ctx.save();
329|        ctx.beginPath();
330|        ctx.arc(size / 2, size / 2, size / 2 - 2, 0, Math.PI * 2);
331|        ctx.clip();
332|        const pts = 50;
333|        ctx.strokeStyle = avatar.color + "bb";
334|        ctx.lineWidth = 2;
335|        ctx.beginPath();
336|        for (let i = 0; i <= pts; i++) {
