73|export default function Home() {
74|  // Support clean /oauth/consent path for OAuth authorization consent screen (SPA fallback via _redirects)
75|  if (typeof window !== "undefined" && window.location.pathname === "/oauth/consent") {
76|    return <OAuthConsent />;
77|  }
78|
79|  const [active, setActive] = useState(() => {
80|    const hash = window.location.hash.replace("#", "").trim();
81|    if (hash) return hash;
82|    return localStorage.getItem("lifeos_active_panel") || "dashboard";
83|  });
84|
85|  // Interactive dotted grid background (black + red hover dots)
86|  // Restored and heavily tuned because it was dropped in a previous UI refactor
87|  // (likely during the move to the current panel/theme/glass system for consistency and theming).
88|  const canvasRef = useRef(null);
89|  const mouseRef = useRef({ x: -9999, y: -9999 });
90|
91|  useEffect(() => {
92|    const canvas = canvasRef.current;
93|    if (!canvas) return;
94|
95|    const ctx = canvas.getContext("2d", { alpha: true });
96|    let rafId = null;
97|    const dpr = Math.min(window.devicePixelRatio || 1, 2);
98|    let lastMove = Date.now();
99|
100|    const resize = () => {
101|      canvas.width = Math.floor(window.innerWidth * dpr);
102|      canvas.height = Math.floor(window.innerHeight * dpr);
103|      canvas.style.width = "100vw";
104|      canvas.style.height = "100vh";
105|    };
106|
107|    const updateMouse = (e) => {
108|      mouseRef.current = { x: e.clientX, y: e.clientY };
109|      lastMove = Date.now();
110|    };
111|
112|    window.addEventListener("resize", resize);
113|    // Attach to document AND window for the most reliable global tracking
114|    // (some child elements or React portals can interfere with single listeners)
115|    document.addEventListener("mousemove", updateMouse, { passive: true });
116|    window.addEventListener("mousemove", updateMouse, { passive: true });
117|    resize();
118|
119|    const DOT_SPACING = 18;   // denser grid for nicer "texture" look
120|    const BASE_ALPHA = 0.07;  // more visible base dots on black so the grid shows under glass modules
121|    const HOVER_R = 100;      // generous hover range so it feels responsive
122|
123|    const draw = () => {
124|      // Force solid black every frame so the background is always pure black
125|      ctx.fillStyle = "#000000";
126|      ctx.fillRect(0, 0, canvas.width, canvas.height);
127|
128|      const { x: mx, y: my } = mouseRef.current;
129|      const timeSinceMove = Date.now() - lastMove;
130|      // After cursor stops moving, the red highlighted grid fades away slowly (~1.2s)
131|      const moveFade = timeSinceMove > 350 ? Math.max(0, 1 - (timeSinceMove - 350) / 1200) : 1;
132|
133|      for (let x = DOT_SPACING / 2; x < window.innerWidth; x += DOT_SPACING) {
134|        for (let y = DOT_SPACING / 2; y < window.innerHeight; y += DOT_SPACING) {
135|          const dx = x - mx;
136|          const dy = y - my;
137|          const dist = Math.hypot(dx, dy);
138|
139|          let alpha = BASE_ALPHA;
140|          let r = 1.1;
141|          let fill = "rgba(140,140,150,";  // faint gray base on black
142|
143|          if (dist < HOVER_R) {
144|            const t = Math.pow(1 - dist / HOVER_R, 1.2) * moveFade;
145|            // Strong lighting up: red dot with large glow so it clearly "lights up" and fades with cursor
146|            alpha = 0.9 * moveFade;
147|            r = 1.5 + t * 2.2;
148|            fill = "rgba(255,0,0,"; // red
149|
150|            // Large glow for visible lighting effect
151|            ctx.beginPath();
152|            ctx.arc(x * dpr, y * dpr, r * dpr * 2.8, 0, Math.PI * 2);
153|            ctx.fillStyle = `rgba(255,0,0,${t * 0.2})`;
154|            ctx.fill();
155|          }
156|
157|          ctx.beginPath();
158|          ctx.arc(x * dpr, y * dpr, r * dpr, 0, Math.PI * 2);
159|          ctx.fillStyle = fill + alpha + ")";
160|          ctx.fill();
161|        }
162|      }
163|
164|      rafId = requestAnimationFrame(draw);
165|    };
166|
167|    draw();
168|
169|    return () => {
170|      cancelAnimationFrame(rafId);
171|      window.removeEventListener("resize", resize);
172|      document.removeEventListener("mousemove", updateMouse);
173|      window.removeEventListener("mousemove", updateMouse);
174|    };
175|  }, []);
176|
177|  useEffect(() => {
178|    window.location.hash = active;
179|    localStorage.setItem("lifeos_active_panel", active);
180|  }, [active]);
181|
182|  const renderPanel = () => {
183|    switch (active) {
184|      case "dashboard":    return <DashboardPanel setActive={setActive} />;
185|      case "aihub":        return <AIHubPanel />;
