4|export function OmniSearchWidget() {
5|  const [query, setQuery] = useState("");
6|  const [results, setResults] = useState([]);
7|  const [loading, setLoading] = useState(false);
8|  const [history, setHistory] = useState(() => {
9|    try {
10|      return JSON.parse(localStorage.getItem("lifeos_search_history") || "[]");
11|    } catch {
12|      return [];
13|    }
14|  });
15|
16|  const saveHistory = (list) => {
17|    localStorage.setItem("lifeos_search_history", JSON.stringify(list));
18|    setHistory(list);
19|  };
20|
21|  const handleSearch = async () => {
22|    if (!query.trim()) return;
23|    setLoading(true);
24|    
25|    // Simulate search results
26|    // In real integration, this would call the OmniSearchOS1 worker endpoint
27|    try {
28|      await new Promise(resolve => setTimeout(resolve, 800));
29|      const mockResults = [
30|        { id: Date.now(), label: `Search result for "${query}"`, type: "web" },
31|        { id: Date.now() + 1, label: `Related: "${query} guide"`, type: "doc" },
32|      ];
33|      setResults(mockResults);
34|      
35|      // Update history
36|      const newHistory = [query, ...history.filter(h => h !== query)].slice(0, 10);
37|      saveHistory(newHistory);
38|    } catch (error) {
39|      setResults([{ id: "error", label: "Search failed: " + error.message, type: "error" }]);
40|    } finally {
41|      setLoading(false);
42|    }
43|  };
44|
45|  return (
46|    <div style={{ fontSize: 8 }}>
47|      <div style={{ fontWeight: 700, marginBottom: 4, color: "var(--crimson)" }}>
48|        OmniSearch
49|      </div>
50|      <div style={{ display: "flex", gap: 4, marginBottom: 4 }}>
51|        <input
52|          value={query}
53|          onChange={e => setQuery(e.target.value)}
54|          onKeyDown={e => e.key === "Enter" && handleSearch()}
55|          placeholder="Search the web, docs, or create"
56|          style={{ flex: 1, fontSize: 8, padding: "2px 4px" }}
57|        />
58|        <Button onClick={handleSearch} disabled={loading} style={{ fontSize: 8, padding: "2px 6px" }}>
59|          {loading ? "…" : "Go"}
60|        </Button>
61|      </div>
62|      {results.length > 0 && (
63|        <div style={{ maxHeight: 60, overflow: "auto" }}>
64|          {results.map(r => (
65|            <div key={r.id} style={{ fontSize: 8, padding: "1px 0", color: r.type === "error" ? "#ff4f5e" : "var(--t2)" }}>
66|              {r.type === "error" ? "⚠ " : "🔍 "}{r.label}
67|            </div>
68|          ))}
69|        </div>
70|      )}
71|      {history.length > 0 && (
72|        <div style={{ marginTop: 4, fontSize: 7, color: "var(--t3)" }}>
73|          Recent: {history.slice(0, 3).join(", ")}
74|        </div>
75|      )}
76|    </div>
77|  );
