2|import { Button } from "@/lib/ui";
3|
4|export function VeritonOSWidget() {
5|  const [status, setStatus] = useState("idle");
6|  const [tasks, setTasks] = useState(() => {
7|    try {
8|      return JSON.parse(localStorage.getItem("lifeos_veriton_tasks") || "[]");
9|    } catch {
10|      return [];
11|    }
12|  });
13|  const [newTask, setNewTask] = useState("");
14|
15|  const saveTasks = (list) => {
16|    localStorage.setItem("lifeos_veriton_tasks", JSON.stringify(list));
17|    setTasks(list);
18|  };
19|
20|  const addTask = () => {
21|    if (!newTask.trim()) return;
22|    const task = { id: Date.now(), label: newTask, done: false };
23|    saveTasks([...tasks, task]);
24|    setNewTask("");
25|  };
26|
27|  const toggleTask = (id) => {
28|    saveTasks(tasks.map(t => t.id === id ? { ...t, done: !t.done } : t));
29|  };
30|
31|  const runWorkflow = async () => {
32|    setStatus("running");
33|    // Simulate VeritonOS1 automation
34|    await new Promise(resolve => setTimeout(resolve, 1500));
35|    setStatus("completed");
36|    setTimeout(() => setStatus("idle"), 3000);
37|  };
38|
39|  return (
40|    <div style={{ fontSize: 8 }}>
41|      <div style={{ fontWeight: 700, marginBottom: 4, color: "var(--crimson)" }}>
42|        VeritonOS Automation
43|      </div>
44|      <div style={{ marginBottom: 4 }}>
45|        <input
46|          value={newTask}
47|          onChange={e => setNewTask(e.target.value)}
48|          onKeyDown={e => e.key === "Enter" && addTask()}
49|          placeholder="Add automation task"
50|          style={{ width: "100%", fontSize: 8, padding: "2px 4px", marginBottom: 2 }}
51|        />
52|        <Button onClick={addTask} style={{ fontSize: 8, padding: "2px 6px", marginRight: 4 }}>
53|          Add Task
54|        </Button>
55|        <Button onClick={runWorkflow} disabled={status === "running"} style={{ fontSize: 8, padding: "2px 6px" }}>
56|          {status === "running" ? "Running..." : "Run Workflow"}
57|        </Button>
58|      </div>
59|      {status !== "idle" && (
60|        <div style={{ fontSize: 7, marginBottom: 4, color: status === "completed" ? "#00ff9d" : "var(--crimson)" }}>
61|          {status === "running" ? "⚙ Running automation..." : "✓ Workflow completed"}
62|        </div>
63|      )}
64|      {tasks.length > 0 && (
65|        <div style={{ maxHeight: 60, overflow: "auto" }}>
66|          {tasks.slice(-5).map(t => (
67|            <div key={t.id} style={{ display: "flex", alignItems: "center", gap: 4, fontSize: 8, padding: "1px 0" }}>
