69|              <span style={{ color: t.done ? "var(--t3)" : "var(--t2)", textDecoration: t.done ? "line-through" : "none" }}>
70|                {t.label}
71|              </span>
72|            </div>
73|          ))}
74|        </div>
75|      )}
76|    </div>
77|  );
