91|  const canvasRef = useRef(null);
92|  const mouseRef = useRef({ x: -9999, y: -9999 });
93|
94|  useEffect(() => {
95|    const canvas = canvasRef.current;
96|    if (!canvas) return;
97|
98|    const ctx = canvas.getContext("2d", { alpha: true });
99|    let rafId = null;
100|    const dpr = Math.min(window.devicePixelRatio || 1, 2);
101|    let lastMove = Date.now();
102|
103|    const resize = () => {
104|      canvas.width = Math.floor(window.innerWidth * dpr);
105|      canvas.height = Math.floor(window.innerHeight * dpr);
106|      canvas.style.width = "100vw";
107|      canvas.style.height = "100vh";
108|    };
109|
110|    const updateMouse = (e) => {
111|      mouseRef.current = { x: e.clientX, y: e.clientY };
112|      lastMove = Date.now();
113|    };
114|
115|    window.addEventListener("resize", resize);
116|    // Attach to document AND window for the most reliable global tracking
117|    // (some child elements or React portals can interfere with single listeners)
118|    document.addEventListener("mousemove", updateMouse, { passive: true });
119|    window.addEventListener("mousemove", updateMouse, { passive: true });
120|    resize();
121|
122|    const DOT_SPACING = 18;   // denser grid for nicer "texture" look
123|    const BASE_ALPHA = 0.07;  // more visible base dots on black so the grid shows under glass modules
124|    const HOVER_R = 100;      // generous hover range so it feels responsive
125|
126|    const draw = () => {
127|      // Force solid black every frame so the background is always pure black
128|      ctx.fillStyle = "#000000";
129|      ctx.fillRect(0, 0, canvas.width, canvas.height);
130|
131|      const { x: mx, y: my } = mouseRef.current;
132|      const timeSinceMove = Date.now() - lastMove;
133|      // After cursor stops moving, the red highlighted grid fades away slowly (~1.2s)
134|      const moveFade = timeSinceMove > 350 ? Math.max(0, 1 - (timeSinceMove - 350) / 1200) : 1;
135|
136|      for (let x = DOT_SPACING / 2; x < window.innerWidth; x += DOT_SPACING) {
137|        for (let y = DOT_SPACING / 2; y < window.innerHeight; y += DOT_SPACING) {
138|          const dx = x - mx;
139|          const dy = y - my;
140|          const dist = Math.hypot(dx, dy);
141|
142|          let alpha = BASE_ALPHA;
143|          let r = 1.1;
144|          let fill = "rgba(140,140,150,";  // faint gray base on black
145|
146|          if (dist < HOVER_R) {
147|            const t = Math.pow(1 - dist / HOVER_R, 1.2) * moveFade;
148|            // Strong lighting up: red dot with large glow so it clearly "lights up" and fades with cursor
149|            alpha = 0.9 * moveFade;
150|            r = 1.5 + t * 2.2;
151|            fill = "rgba(255,0,0,"; // red
152|
153|            // Large glow for visible lighting effect
154|            ctx.beginPath();
155|            ctx.arc(x * dpr, y * dpr, r * dpr * 2.8, 0, Math.PI * 2);
156|            ctx.fillStyle = `rgba(255,0,0,${t * 0.2})`;
157|            ctx.fill();
158|          }
159|
160|          ctx.beginPath();
161|          ctx.arc(x * dpr, y * dpr, r * dpr, 0, Math.PI * 2);
162|          ctx.fillStyle = fill + alpha + ")";
163|          ctx.fill();
164|        }
165|      }
166|
167|      rafId = requestAnimationFrame(draw);
168|    };
169|
170|    draw();
