71|export function YouTubeDashboard() {
72|  const { youtube, setYoutubeVideo, stopYoutube } = useGlobalPlayback();
73|  const [q, setQ] = useState("");
74|  const [results, setResults] = useState([]);
75|  const [loading, setLoading] = useState(false);
76|  const activeId = youtube?.videoId;
77|
78|  async function search() {
79|    const id = parseYoutubeId(q);
80|    if (id) {
81|      setYoutubeVideo(id, q);
82|      return;
83|    }
84|    setLoading(true);
85|    try {
86|      const r = await fetch(`${WORKER}/api/youtube/videos?max=8`);
87|      const data = await r.json();
88|      const items = (data?.videos || data?.items || []).filter((v) =>
89|        !q.trim() ? true : (v.title || "").toLowerCase().includes(q.toLowerCase())
90|      );
91|      setResults(items.slice(0, 6));
92|    } catch {
93|      setResults([]);
94|    } finally {
95|      setLoading(false);
96|    }
97|  }
98|
99|  return (
100|    <div>
101|      <div style={{ display: "flex", gap: 4, marginBottom: 4 }}>
102|        <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search or paste YouTube URL" style={{ flex: 1, fontSize: 8, padding: "2px 4px" }} onKeyDown={(e) => e.key === "Enter" && search()} />
103|        <button type="button" onClick={search} style={{ fontSize: 8, padding: "2px 6px" }}>{loading ? "…" : "Go"}</button>
104|        <button type="button" onClick={stopYoutube} style={{ fontSize: 8, padding: "2px 6px" }} title="Stop">■</button>
105|      </div>
106|      {activeId ? (
107|      <iframe
108|        title="YouTube player"
109|        style={{ width: "100%", height: 168, border: 0, borderRadius: 4 }}
110|        src={`https://www.youtube.com/embed/${activeId}?autoplay=0&enablejsapi=1`}
111|        allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
112|      />
113|      ) : (
114|        <div style={{ height: 168, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 9, color: "var(--t3)" }}>Search or paste a URL to play</div>
115|      )}
116|      {results.length > 0 && (
117|        <div style={{ fontSize: 7, marginTop: 4, maxHeight: 48, overflow: "auto" }}>
118|          {results.map((v, i) => (
119|            <button key={i} type="button" onClick={() => setYoutubeVideo(v.id || v.videoId, v.title)} style={{ display: "block", width: "100%", textAlign: "left", background: "transparent", border: "none", color: "var(--t2)", cursor: "pointer", padding: "1px 0" }}>
120|              {v.title}
121|            </button>
122|          ))}
123|        </div>
124|      )}
125|    </div>
126|  );
