import React, { useState, useEffect } from "react";
import { Button } from "@/lib/ui";

export function OmniSearchWidget() {
  const [query, setQuery] = useState("");
  const [results, setResults] = useState([]);
  const [loading, setLoading] = useState(false);
  const [history, setHistory] = useState(() => {
    try {
      return JSON.parse(localStorage.getItem("lifeos_search_history") || "[]");
    } catch {
      return [];
    }
  });

  const saveHistory = (list) => {
    localStorage.setItem("lifeos_search_history", JSON.stringify(list));
    setHistory(list);
  };

  const handleSearch = async () => {
    if (!query.trim()) return;
    setLoading(true);

    // Simulate search results
    // In real integration, this would call the OmniSearchOS1 worker endpoint
    try {
      await new Promise(resolve => setTimeout(resolve, 800));
      const mockResults = [
        { id: Date.now(), label: `Search result for "${query}"`, type: "web" },
        { id: Date.now() + 1, label: `Related: "${query} guide"`, type: "doc" },
      ];
      setResults(mockResults);

      // Update history
      const newHistory = [query, ...history.filter(h => h !== query)].slice(0, 10);
      saveHistory(newHistory);
    } catch (error) {
      setResults([{ id: "error", label: \"Search failed: \" + error.message, type: \"error\" }]);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{ fontSize: 8 }}>
      <div style={{ fontWeight: 700, marginBottom: 4, color: \"var(--crimson)\" }}>
        OmniSearch
      </div
      <div style={{ display: \"flex\", gap: 4, marginBottom: 4 }}>
        <input
          value={query}
          onChange={e => setQuery(e.target.value)}
          onKeyDown={e => e.key === \"Enter\" && handleSearch()}
          placeholder=\"Search the web, docs, or create\"
          style={{ flex: 1, fontSize: 8, padding: \"2px 4px\" }}
        />
        <Button onClick={handleSearch} disabled={loading} style={{ fontSize: 8, padding: \"2px 6px\" }}>
          {loading ? \"…\" : \"Go\"}
        </Button>
      </div
      {results.length > 0 && (
        <div style={{ maxHeight: 60, overflow: \"auto\" }}>
          {results.map(r => (
            <div key={r.id} style={{ fontSize: 8, padding: \"1px 0\", color: r.type === \"error\" ? \"#ff4f5e\" : \"var(--t2)\" }}>
              {r.type === \"error\" ? \"⚠ \" : \"🔍 \"}{r.label}
            </div
          ))}
        </div
      )}
      {history.length > 0 && (
        <div style={{ marginTop: 4, fontSize: 7, color: \"var(--t3)\" }}>
          Recent: {history.slice(0, 3).join(\", \")}
        </div
      )}
    </div
  );
}
